const {chromium}=require('playwright'),assert=require('node:assert/strict');
(async()=>{const base=process.env.ALPHA_BASE_URL||'https://tuuvo.app.br',browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/usr/bin/google-chrome'});try{const page=await browser.newPage({viewport:{width:1280,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto(base+'/experience');await page.locator('#select-corporate').click();await page.locator('[data-choice="marina"]').waitFor();assert.equal(await page.locator('#actions button').count(),3);assert.equal(await page.locator('#scene').isVisible(),true);await page.screenshot({path:'/tmp/alpha-browser/marina-historia-inicio.png',fullPage:true});
let fail=true;await page.route('**/api/demo/step',async r=>{if(fail){fail=false;await r.fulfill({status:503,body:'{}'})}else await r.continue()});await page.locator('[data-choice="marina"]').click();await page.locator('#error').filter({hasText:/Tente novamente/}).waitFor();assert.equal(await page.locator('[data-choice="marina"]').isEnabled(),true);await page.locator('[data-choice="marina"]').click();await page.locator('[data-choice="regular"]').waitFor();assert.match(await page.locator('#message').textContent(),/duas turmas/);await page.reload();await page.locator('[data-choice="regular"]').waitFor();await page.locator('[data-choice="regular"]').click();await page.locator('#ending').waitFor({state:'visible'});assert.match(await page.locator('#facts').textContent(),/2 horas/);assert.match(await page.locator('#facts').textContent(),/R\$ 0/);await page.screenshot({path:'/tmp/alpha-browser/marina-duas-turmas.png',fullPage:true});const dl=page.waitForEvent('download');await page.locator('#download').click();assert.equal((await dl).suggestedFilename(),'coonto-marina-percurso.txt');await page.locator('#ending summary').click();await page.locator('#trail button').first().click();await page.locator('[data-choice="reservar"]').click();await page.locator('[data-choice="cadastro"]').click();await page.locator('[data-choice="esperar"]').waitFor();assert.match(await page.locator('#title').textContent(),/lado de fora/);assert.match(await page.locator('#facts').textContent(),/120/);await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:'/tmp/alpha-browser/marina-porta-mobile.png',fullPage:true});await page.reload();await page.locator('[data-choice="esperar"]').click();await page.locator('#ending').waitFor({state:'visible'});assert.match(await page.locator('#facts').textContent(),/600/);assert.match(await page.locator('#facts').textContent(),/10 minutos/);
await page.locator('.feedback summary').click();await page.locator('[name="suggestion"]').fill('Uma sugestão de clareza para o caso.');let payload;await page.route('**/api/experience-feedback',async r=>{payload=r.request().postDataJSON();await r.fulfill({status:201,contentType:'application/json',body:'{"saved":true}'})});await page.locator('#feedbackForm button').click();await page.locator('#feedbackStatus').filter({hasText:/recebido/}).waitFor();assert.equal(payload.experienceVersion,'3');assert.equal(payload.phase,'espera');assert.equal(payload.history,undefined);await page.locator('#restart').click();await page.locator('[data-choice="reservar"]').click();await page.locator('[data-choice="recebedor"]').click();await page.locator('#ending').waitFor({state:'visible'});assert.match(await page.locator('#facts').textContent(),/480/);assert.match(await page.locator('#title').textContent(),/antes/);assert.deepEqual(errors,[]);console.log('PASS: continuous story, real branching outcomes, action failure retry, resume, mobile, replay at decision, export and private feedback context');}finally{await browser.close()}})().catch(e=>{console.error('::error title=Narrative journey validation::'+e.message.replace(/\n/g,'%0A'));process.exit(1)});
